const records = $input.first().json.records || [];
if (!records.length) {
  return [{ json: { _empty: true, error: 'No active brands with ad accounts found' } }];
}

const brands = records.map(r => ({
  json: {
    _empty: false,
    brand_record_id: r.id,
    brand_name: r.fields.brand_name || 'Unknown Brand',
    ad_account_id: r.fields.ad_account_id,
    roas_target: parseFloat(r.fields.roas_target) || 3.0,
    insights_url: `https://graph.facebook.com/v21.0/act_${r.fields.ad_account_id}/insights?fields=campaign_name,campaign_id,spend,impressions,clicks,cpc,cpm,frequency,actions,action_values&date_preset=last_7d&level=campaign&limit=50`
  }
}));

return brands;

const input = $input.first().json;
const data = input.data || [];

// Carry forward brand context from previous node via $('Build Meta API Requests')
let brand_name = 'Unknown Brand';
let roas_target = 3.0;
let ad_account_id = '';

try {
  const prev = $('Build Meta API Requests').first().json;
  brand_name = prev.brand_name || brand_name;
  roas_target = prev.roas_target || roas_target;
  ad_account_id = prev.ad_account_id || ad_account_id;
} catch (e) {
  // fallback
}

if (!data.length) {
  return [{
    json: {
      brand_name,
      ad_account_id,
      roas_target,
      has_data: false,
      summary: `No campaign data found for ${brand_name} (act_${ad_account_id}) in the last 7 days.`,
      campaigns: [],
      totals: { spend: 0, impressions: 0, clicks: 0, purchases: 0, revenue: 0, roas: 0 }
    }
  }];
}

let totalSpend = 0;
let totalImpressions = 0;
let totalClicks = 0;
let totalPurchases = 0;
let totalRevenue = 0;

const campaigns = data.map(c => {
  const spend = parseFloat(c.spend || 0);
  const impressions = parseInt(c.impressions || 0);
  const clicks = parseInt(c.clicks || 0);
  const frequency = parseFloat(c.frequency || 0);
  const cpc = parseFloat(c.cpc || 0);
  const cpm = parseFloat(c.cpm || 0);

  const actions = c.actions || [];
  const actionValues = c.action_values || [];

  const purchaseAction = actions.find(a => a.action_type === 'purchase') || {};
  const purchaseValue = actionValues.find(a => a.action_type === 'purchase') || {};
  const purchases = parseInt(purchaseAction.value || 0);
  const revenue = parseFloat(purchaseValue.value || 0);
  const roas = spend > 0 ? revenue / spend : 0;

  // Fatigue detection
  const is_fatigued = frequency > 3;

  // ROAS flags
  const roas_below_target = roas > 0 && roas < roas_target;
  const roas_strong = roas >= roas_target;

  totalSpend += spend;
  totalImpressions += impressions;
  totalClicks += clicks;
  totalPurchases += purchases;
  totalRevenue += revenue;

  return {
    campaign_name: c.campaign_name || c.campaign_id,
    campaign_id: c.campaign_id,
    spend: spend.toFixed(2),
    impressions,
    clicks,
    cpc: cpc.toFixed(2),
    cpm: cpm.toFixed(2),
    frequency: frequency.toFixed(2),
    purchases,
    revenue: revenue.toFixed(2),
    roas: roas.toFixed(2),
    is_fatigued,
    roas_below_target,
    roas_strong
  };
});

// Sort by spend desc
campaigns.sort((a, b) => parseFloat(b.spend) - parseFloat(a.spend));

const overallRoas = totalSpend > 0 ? (totalRevenue / totalSpend) : 0;

// Flag summary
const fatiguedCampaigns = campaigns.filter(c => c.is_fatigued);
const underperformers = campaigns.filter(c => c.roas_below_target);
const topPerformers = campaigns.filter(c => c.roas_strong).sort((a, b) => parseFloat(b.roas) - parseFloat(a.roas));

return [{
  json: {
    brand_name,
    ad_account_id,
    roas_target,
    has_data: true,
    totals: {
      spend: totalSpend.toFixed(2),
      impressions: totalImpressions,
      clicks: totalClicks,
      purchases: totalPurchases,
      revenue: totalRevenue.toFixed(2),
      roas: overallRoas.toFixed(2),
      ctr: totalImpressions > 0 ? ((totalClicks / totalImpressions) * 100).toFixed(2) : '0.00'
    },
    campaigns,
    fatigued_count: fatiguedCampaigns.length,
    underperformer_count: underperformers.length,
    top_performer_count: topPerformers.length,
    fatigued_campaigns: fatiguedCampaigns.map(c => c.campaign_name),
    underperforming_campaigns: underperformers.map(c => `${c.campaign_name} (${c.roas} ROAS vs ${roas_target} target)`),
    top_campaigns: topPerformers.slice(0, 3).map(c => `${c.campaign_name} (${c.roas} ROAS)`)
  }
}];

