const input = $input.first().json;

// Extract Gemini response
let analysis = 'Unable to generate analysis.';
try {
  analysis = input.candidates[0].content.parts[0].text;
} catch (e) {
  analysis = `Gemini analysis failed: ${e.message}. Raw: ${JSON.stringify(input).substring(0, 500)}`;
}

// Get brand context from upstream
let brand_name = 'Unknown Brand';
let totals = {};
let roas_target = 3.0;
try {
  const agg = $('Aggregate Campaign Results').first().json;
  brand_name = agg.brand_name;
  totals = agg.totals;
  roas_target = agg.roas_target;
} catch (e) {}

// Build Slack message
const roasEmoji = parseFloat(totals.roas || 0) >= roas_target ? ':white_check_mark:' : ':warning:';
const header = `:bar_chart: *Media Monitor — ${brand_name}* (Last 7 Days)\n${roasEmoji} Spend: $${totals.spend || '0'} | Revenue: $${totals.revenue || '0'} | ROAS: ${totals.roas || '0'}x (target ${roas_target}x)\n---`;

const message = `${header}\n\n${analysis}`;

return [{ json: { brand_name, message, totals, roas_target } }];

const brand_name = $json.brand_name || 'Unknown';
const summary = $json.summary || `No data for ${brand_name}`;

const message = `:bar_chart: *Media Monitor — ${brand_name}*\n${summary}`;

return [{ json: { brand_name, message } }];
